def build_command(command_name: str, *params: Any) -> str:
    """Build a serial command string."""
    if not params:
        return command_name
    return f"{command_name} " + ",".join(str(p) for p in params)


def get_command_meta(command_name: str) -> dict:
    """Return metadata for a command."""
    return COMMANDS[command_name]


def sensor_values_to_dict(values: list[Any]) -> dict[str, Any]:
    """Map SENSORS_GET_VALUES payload list to a keyed dictionary.

    Note:
        The spreadsheet contains duplicate raw keys for OFFSET fields.
        To avoid overwriting values, this function uses ``dict_key`` from
        SENSOR_FIELDS, which is guaranteed to be unique.
    """
    result: dict[str, Any] = {}
    for field, value in zip(SENSOR_FIELDS, values):
        result[field["dict_key"]] = value
    return result


def is_async_message(message: str) -> bool:
    """Check whether a raw message starts with a known async event name."""
    msg = message.strip()
    for name in ASYNC_MESSAGES:
        if msg.startswith(name) or msg.startswith(f"[{name}]"):
            return True
    return False